#include <teaql/runtime/context.hpp>
#include <teaql/runtime/event.hpp>
#include <teaql/runtime/log_formatter.hpp>
#include <teaql/runtime/detail/audit_privacy.hpp>
#include <teaql/core/detail/debug.hpp>
#include <teaql/core/detail/model_json.hpp>
#include "fixture_value.hpp"
#include <bit>
#include <cstdlib>
#include <iostream>
using namespace teaql;
static Json opt(Memory r,const std::optional<String>& s){return s?Json(r,*s):Json(r);}
static Json length(Memory r,std::optional<std::size_t> n){return n?Json(r,*n):Json(r);}
static Value input_value(Memory r,const Json& j){auto kind=text(field(j,"kind"));if(kind=="f64_bits"){auto s=text(field(j,"value"));std::uint64_t n=0;std::from_chars(s.data(),s.data()+s.size(),n,16);return Value(r,std::bit_cast<double>(n));}if(kind=="object"){Record values(r);for(const auto& [k,v]:std::get<Json::Object>(field(j,"value").data))values.emplace(k,input_value(r,v));return Value(r,values);}if(kind=="list"){Value::List values(r);for(const auto& v:std::get<Json::Array>(field(j,"value").data))values.emplace_back(input_value(r,v));return Value(r,values);}return value(r,j);}
static Record record(Memory r,const Json& j){Record values(r);for(const auto& [k,v]:std::get<Json::Object>(j.data))values.emplace(k,input_value(r,v));return values;}
static Vector<String> strings(Memory r,const Json& j){Vector<String> out(r);for(const auto& s:std::get<Json::Array>(j.data))out.emplace_back(text(s));return out;}
static std::optional<Record> old_record(Memory r,const Json& j){if(std::holds_alternative<std::monostate>(j.data))return {};return record(r,j);}
static std::optional<std::size_t> maximum(const Json& j){return std::holds_alternative<std::monostate>(j.data)?std::nullopt:std::optional<std::size_t>(std::get<std::uint64_t>(j.data));}
static std::string_view kind(RawAuditEventKind k){constexpr std::string_view names[]{"Created","Updated","Deleted","Recovered","SchemaCreated","SchemaVerified","FieldAdded","DataSeeded"};return names[unsigned(k)];}
static Json record_out(Memory r,const Record& values){auto out=detail::model_json(r);for(const auto& [k,v]:values)detail::model_put(out,k,detail::debug_value(r,v));return out;}
static Json trace_out(Memory r,const TraceChain& trace){Json::Array out(r);for(const auto& n:trace){auto item=detail::model_json(r);detail::model_put(item,"entity",n.entity_type);detail::model_put(item,"comment",n.comment);String id(r);if(n.entity_id){char b[32];auto end=std::to_chars(b,b+32,*n.entity_id).ptr;id.append(b,end);}detail::model_put(item,"id",n.entity_id?Json(r,id):Json(r));out.emplace_back(std::move(item));}return Json(r,out);}
static Json string_array(Memory r,const Vector<String>& strings){Json::Array out(r);for(const auto& s:strings)out.emplace_back(s);return Json(r,out);}
static Json governance(Memory r,const std::optional<MutationGovernanceSnapshot>& g){if(!g)return Json(r);auto out=detail::model_json(r);detail::model_put(out,"execution",g->execution_id);detail::model_put(out,"request",g->request_key);detail::model_put(out,"source",g->source==MutationPolicySource::Customer?"Customer":"GeneratedDefault");detail::model_put(out,"approval",g->approval_status==MutationPolicyApprovalStatus::Approved?"Approved":g->approval_status==MutationPolicyApprovalStatus::Missing?"Missing":"NotApplicable");Json::Array policy(r);if(g->policy){policy.emplace_back(g->policy->id);policy.emplace_back(g->policy->version);policy.emplace_back(g->policy->fingerprint);}detail::model_put(out,"policy",g->policy?Json(r,policy):Json(r));detail::model_put(out,"warnings",string_array(r,g->warning_codes));Json::Array ops(r);for(const auto& o:g->operations){auto item=detail::model_json(r);constexpr std::string_view names[]{"Create","Update","Delete","Recover"};detail::model_put(item,"kind",names[unsigned(o.kind)]);detail::model_put(item,"entity",o.entity.entity);detail::model_put(item,"id",detail::debug_value(r,o.entity.id));detail::model_put(item,"fields",string_array(r,o.changed_fields));ops.emplace_back(std::move(item));}detail::model_put(out,"operations",ops);return out;}
static RawAuditEvent raw(Memory r,const Json& j){auto entity=text(field(j,"entity")),k=text(field(j,"kind"));auto values=record(r,field(j,"values"));auto id=input_value(r,field(j,"id"));auto old=old_record(r,field(j,"old"));std::optional<std::int64_t> version;if(std::holds_alternative<String>(field(j,"version").data))version=number<std::int64_t>(field(j,"version"));auto e=[&]{
    if(k=="created")return RawAuditEvent::created(r,entity,values);if(k=="updated")return RawAuditEvent::updated(r,entity,values);if(k=="updated_old")return RawAuditEvent::updated_with_old_values(r,entity,values,old,record(r,field(j,"new")),strings(r,field(j,"fields")));
    if(k=="deleted")return RawAuditEvent::deleted(r,entity,id,version);if(k=="deleted_old")return RawAuditEvent::deleted_with_old_values(r,entity,id,version,old);if(k=="recovered")return RawAuditEvent::recovered(r,entity,id,*version);if(k=="recovered_old")return RawAuditEvent::recovered_with_old_values(r,entity,id,*version,old);
    if(k=="schema_created")return RawAuditEvent::schema_created(r,entity,text(field(j,"table")),number<std::size_t>(field(j,"count")));if(k=="schema_verified")return RawAuditEvent::schema_verified(r,entity,text(field(j,"table")),number<std::size_t>(field(j,"count")));if(k=="field_added")return RawAuditEvent::field_added(r,entity,text(field(j,"table")),text(field(j,"field")));return RawAuditEvent::data_seeded(r,entity,text(field(j,"table")),number<std::size_t>(field(j,"count")),number<std::size_t>(field(j,"updated")));
    }();
    for(const auto& t:std::get<Json::Array>(field(j,"trace").data))e.trace_chain.emplace_back(TraceKind::AuditReason,text(field(t,"entity")),text(field(t,"comment")),1001);
    if(std::get<bool>(field(j,"bootstrap").data))e.bootstrap_audit.emplace(std::allocator_arg,Allocator(r),"actor secret 1001","category secret","reason secret 1001",-3,1234);
    if(std::get<bool>(field(j,"governance").data)){e.mutation_governance.emplace(std::allocator_arg,Allocator(r),"execution secret","request secret",MutationPolicySource::Customer,MutationPolicyApprovalStatus::Approved);auto& g=*e.mutation_governance;g.policy.emplace(std::allocator_arg,Allocator(r),"policy secret","v1","fingerprint");g.warning_codes.emplace_back("warning");EntityKey key(std::allocator_arg,Allocator(r),"Order",Value(r,std::uint64_t(1001)));g.operations.emplace_back(MutationOperationKind::Update,key);g.operations.back().changed_fields.emplace_back("secret");g.operations.back().changed_fields.emplace_back("field");}return e;
}
static Json raw_out(Memory r,const RawAuditEvent& e){auto out=detail::model_json(r);detail::model_put(out,"kind",kind(e.kind));detail::model_put(out,"entity",e.entity);detail::model_put(out,"values",record_out(r,e.values));detail::model_put(out,"fields",string_array(r,e.updated_fields));detail::model_put(out,"old",e.old_values?record_out(r,*e.old_values):Json(r));detail::model_put(out,"new",e.new_values?record_out(r,*e.new_values):Json(r));Json::Array changes(r);for(const auto& c:e.changes){auto item=detail::model_json(r);detail::model_put(item,"field",c.field);detail::model_put(item,"old",c.old_value?Json(r,detail::debug_value(r,*c.old_value)):Json(r));detail::model_put(item,"new",c.new_value?Json(r,detail::debug_value(r,*c.new_value)):Json(r));changes.emplace_back(std::move(item));}detail::model_put(out,"changes",changes);detail::model_put(out,"trace",trace_out(r,e.trace_chain));auto boot=Json(r);if(e.bootstrap_audit){boot=detail::model_json(r);auto& b=*e.bootstrap_audit;detail::model_put(boot,"actor",b.actor);detail::model_put(boot,"category",b.category);detail::model_put(boot,"reason",b.reason);detail::model_put(boot,"version",b.resulting_version?Json(r,*b.resulting_version):Json(r));detail::model_put(boot,"time",b.occurred_at_millis);}detail::model_put(out,"bootstrap",boot);detail::model_put(out,"governance",governance(r,e.mutation_governance));return out;}
static Json field_out(Memory r,const SafeAuditField& f){auto out=detail::model_json(r);detail::model_put(out,"name",f.name);detail::model_put(out,"value",opt(r,f.value));detail::model_put(out,"masked",f.masked);detail::model_put(out,"truncated",f.truncated);detail::model_put(out,"raw_length",length(r,f.raw_length));detail::model_put(out,"output_length",length(r,f.output_length));detail::model_put(out,"mask_reason",opt(r,f.mask_reason));detail::model_put(out,"truncate_reason",opt(r,f.truncate_reason));return out;}
static Json evaluate(Memory r,const Json& j){auto* ack=optional(j,"ack");if(ack && std::holds_alternative<String>(ack->data))setenv("TEAQL_ALLOW_SENSITIVE_PLAINTEXT_LOGS",std::get<String>(ack->data).c_str(),1);else unsetenv("TEAQL_ALLOW_SENSITIVE_PLAINTEXT_LOGS");auto op=text(field(j,"op"));
    if(op=="debug")return Json(r,detail::debug_value(r,input_value(r,field(j,"value"))));
    if(op=="key"){EntityKey a(std::allocator_arg,Allocator(r),text(field(j,"a_entity")),input_value(r,field(j,"a"))),b(std::allocator_arg,Allocator(r),text(field(j,"b_entity")),input_value(r,field(j,"b")));if(auto* v=optional(j,"mutated"))a.id=input_value(r,*v);EntityKey copy(std::allocator_arg,Allocator(r),a);auto out=detail::model_json(r);detail::model_put(out,"eq",copy==b);auto c=copy<=>b;detail::model_put(out,"cmp",c<0?-1:c>0?1:0);return out;}
    if(op=="identity"){auto out=detail::model_json(r);try{MutationPolicyIdentity id(std::allocator_arg,Allocator(r),text(field(j,"id")),text(field(j,"version")),text(field(j,"fingerprint")));detail::model_put(out,"id",id.id);detail::model_put(out,"version",id.version);detail::model_put(out,"fingerprint",id.fingerprint);}catch(const std::invalid_argument& e){detail::model_put(out,"panic",std::string_view(e.what()));}return out;}
    if(op=="limit"){auto result=limit_audit_value(r,text(field(j,"raw")),number<std::size_t>(field(j,"max")));auto out=detail::model_json(r);detail::model_put(out,"text",result.first);detail::model_put(out,"truncated",result.second);return out;}
    auto masks=strings(r,field(j,"masks"));auto max=maximum(field(j,"max"));
    if(op=="field"){std::optional<std::string_view> raw;if(std::holds_alternative<String>(field(j,"raw").data))raw=text(field(j,"raw"));return field_out(r,build_safe_audit_field(r,text(field(j,"name")),raw,masks,max));}
    auto e=raw(r,j);if(auto* format=optional(j,"formatter");format && std::get<bool>(format->data)){HumanReaderFormatter human;DebugReaderFormatter debug;auto out=detail::model_json(r);auto strip=[](String text){text.erase(0,text.find("]-")+1);return text;};detail::model_put(out,"human",strip(human.format_audit_log(r,e)));detail::model_put(out,"human_sensitive",strip(human.format_sensitive_audit_log(r,e)));detail::model_put(out,"debug",debug.format_audit_log(r,e));detail::model_put(out,"debug_sensitive",debug.format_sensitive_audit_log(r,e));return out;}auto before=raw_out(r,e);auto safe=e.build_safe_event(r,masks,max);auto safe_out=detail::model_json(r);detail::model_put(safe_out,"kind",kind(safe.kind));detail::model_put(safe_out,"entity",safe.entity);Json::Array fields(r);for(const auto& f:safe.fields)fields.emplace_back(field_out(r,f));detail::model_put(safe_out,"fields",fields);detail::model_put(safe_out,"trace",trace_out(r,safe.trace_chain));detail::model_put(safe_out,"governance",governance(r,safe.mutation_governance));auto out=detail::model_json(r);detail::model_put(out,"raw",before);detail::model_put(out,"unchanged",raw_out(r,e)==before);detail::model_put(out,"safe",safe_out);detail::model_put(out,"projection",raw_out(r,detail::audit_event_projection(r,e,std::get<bool>(field(j,"allow").data))));return out;
}
int main(){GlobalContext global;std::string line;while(std::getline(std::cin,line)){auto context=global.make_user_context();auto r=context->memory_resource();auto j=Json::parse(r,line);if(!j)throw std::runtime_error("invalid input");std::cout<<evaluate(r,*j).dump(r)<<'\n';}}
